import path from 'node:path'
import * as p from '@clack/prompts'
import pc from 'picocolors'
import { projectPaths } from '../../core/paths.js'
import { existingSddPath } from '../../core/config.js'
import { createTask } from '../../core/skeleton.js'

/**
 * `excalibur new <repo> <task-slug> [--class fix|feature|big-feature]` — create a task
 * folder in the SDD from the pipeline template, with the frontmatter already filled in.
 * Generated by code so the structure never depends on an agent remembering it; `lint`
 * checks it afterwards.
 */
export async function newTask(args, cwd) {
  const quiet = Boolean(args.quiet)
  if (!quiet) p.intro(pc.bgCyan(pc.black(' excalibur new ')))

  if (!projectPaths(cwd).configured) {
    p.cancel('No config found here. Run `npx @easy-spec/excalibur init` first.')
    return 1
  }

  const root = existingSddPath(cwd)
  if (!root) {
    p.cancel('The SDD folder does not exist yet. Finish onboarding with /excalibur-init first.')
    return 1
  }

  const [repo, slug] = args._
  if (!repo || !slug) {
    p.cancel('Usage: excalibur new <repo> <task-slug> [--class fix|feature|big-feature]')
    return 1
  }

  try {
    const { dir, written } = createTask(cwd, root, {
      repo: String(repo),
      slug: String(slug),
      klass: args.class ? String(args.class) : 'feature',
    })
    p.note(`${path.relative(cwd, dir)}/\n${written.map((f) => `  ${f}`).join('\n')}`, 'Task created')
    if (!quiet) p.outro('Fill in the proposal first. history.yaml is written by the review step, never by hand.')
    return 0
  } catch (error) {
    p.cancel(error.message)
    return 1
  }
}
